";lbl.TextColor3=Color3.fromRGB(0,255,70);lbl.Font=Enum.Font.Code;lbl.TextSize=16;lbl.Parent=matrixGui;lbl:TweenPosition(UDim2.new(lbl.Position.X.Scale,0,1.2,0),Enum.EasingDirection.In,Enum.EasingStyle.Linear,math.random(3,7),true);end task.delay(7,function() if matrixGui then matrixGui:Destroy();end end);end local rainbowActive=false;local rainbowConn=nil;local function cmdRainbow() rainbowActive= not rainbowActive;if rainbowActive then rainbowConn=RunService.RenderStepped:Connect(function() local char=localPlayer.Character;if char then local color=Color3.fromHSV(tick()%1 ,1,1);for _,part in ipairs(char:GetChildren()) do if part:IsA("BasePart") then part.Color=color;end end end end);elseif rainbowConn then rainbowConn:Disconnect();end end local function cmdScale(scale) local char=localPlayer.Character;if char then local humanoid=char:FindFirstChildOfClass("Humanoid");if humanoid then for _,prop in ipairs({"BodyHeightScale","BodyWidthScale","BodyDepthScale","HeadScale"}) do local val=humanoid:FindFirstChild(prop);if val then val.Value=scale;end end end end end local noclipActive=false;local noclipConn=nil;local function cmdNoclip() noclipActive= not noclipActive;if noclipActive then noclipConn=RunService.Stepped:Connect(function() local char=localPlayer.Character;if char then for _,part in ipairs(char:GetChildren()) do if part:IsA("BasePart") then part.CanCollide=false;end end end end);elseif noclipConn then noclipConn:Disconnect();end end local function cmdFart() local sound=Instance.new("Sound");sound.SoundId="rbxassetid://130833677";sound.Volume=1;sound.Parent=workspace;sound:Play();task.delay(3,function() sound:Destroy();end);end local function cmdJump(power) local char=localPlayer.Character;if char then local humanoid=char:FindFirstChildOfClass("Humanoid");if humanoid then humanoid.UseJumpPower=true;humanoid.JumpPower=tonumber(power) or 50 ;end end end local isFlying=false;local bodyVel,bodyGyro;local function cmdSuperman() local root=getRootPart();if  not root then return;end isFlying= not isFlying;if isFlying then bodyVel=Instance.new("BodyVelocity");bodyVel.Name="SupermanVelocity";bodyVel.MaxForce=Vector3.new(1,1,1) * (10^6) ;bodyVel.Velocity=Vector3.new(0,50,0);bodyVel.Parent=root;bodyGyro=Instance.new("BodyGyro");bodyGyro.Name="SupermanGyro";bodyGyro.MaxTorque=Vector3.new(1,1,1) * (10^6) ;bodyGyro.CFrame=root.CFrame;bodyGyro.Parent=root;else if bodyVel then bodyVel:Destroy();end if bodyGyro then bodyGyro:Destroy();end end end local boomboxFrame=nil;local localSound=Instance.new("Sound");localSound.Name="LocalBoomboxSound";localSound.Parent=workspace;local function cmdBoombox() if boomboxFrame then boomboxFrame.Visible= not boomboxFrame.Visible;return;end boomboxFrame=Instance.new("Frame");boomboxFrame.Name="BoomboxPanel";boomboxFrame.Size=UDim2.new(0,230,0,130);boomboxFrame.Position=UDim2.new(0.5,250,0.5, -65);boomboxFrame.BackgroundColor3=Color3.fromRGB(35,35,35);boomboxFrame.BorderSizePixel=0;boomboxFrame.Parent=screenGui;local bbCorner=Instance.new("UICorner");bbCorner.CornerRadius=UDim.new(0,6);bbCorner.Parent=boomboxFrame;local bbTop=Instance.new("Frame");bbTop.Size=UDim2.new(1,0,0,25);bbTop.BackgroundColor3=Color3.fromRGB(20,20,20);bbTop.BorderSizePixel=0;bbTop.Parent=boomboxFrame;local bbTitle=Instance.new("TextLabel");bbTitle.Size=UDim2.new(1, -30,1,0);bbTitle.Position=UDim2.new(0,8,0,0);bbTitle.BackgroundTransparency=1;bbTitle.Text="Boombox Panel (Local)";bbTitle.TextColor3=Color3.fromRGB(255,255,255);bbTitle.TextXAlignment=Enum.TextXAlignment.Left;bbTitle.Font=Enum.Font.SourceSansBold;bbTitle.TextSize=13;bbTitle.Parent=bbTop;local bbClose=Instance.new("TextButton");bbClose.Size=UDim2.new(0,25,1,0);bbClose.Position=UDim2.new(1, -25,0,0);bbClose.BackgroundTransparency=1;bbClose.Text="X";bbClose.TextColor3=Color3.fromRGB(255,255,255);bbClose.Font=Enum.Font.SourceSansBold;bbClose.Parent=bbTop;local idBox=Instance.new("TextBox");idBox.Size=UDim2.new(1, -20,0,30);idBox.Position=UDim2.new(0,10,0,35);idBox.BackgroundColor3=Color3.fromRGB(20,20,20);idBox.TextColor3=Color3.fromRGB(255,255,255);idBox.PlaceholderText="Ingresa Sound ID...";idBox.Font=Enum.Font.SourceSans;idBox.TextSize=14;idBox.Parent=boomboxFrame;local playBtn=Instance.new("TextButton");playBtn.Size=UDim2.new(1, -20,0,30);playBtn.Position=UDim2.new(0,10,0,75);playBtn.BackgroundColor3=Color3.fromRGB(0,180,80);playBtn.Text="Reproducir Audio";playBtn.TextColor3=Color3.fromRGB(255,255,255);playBtn.Font=Enum.Font.SourceSansBold;playBtn.TextSize=14;playBtn.BorderSizePixel=0;playBtn.Parent=boomboxFrame;playBtn.MouseButton1Click:Connect(function() local cleanId=string.gsub(idBox.Text,"%D","");if (cleanId~="") then localSound.SoundId="rbxassetid://"   .. cleanId ;localSound:Play();end end);bbClose.MouseButton1Click:Connect(function() boomboxFrame.Visible=false;end);end local function cmdByeBye() localPlayer:Kick("\n[RC7 Client] Te has desconectado usando el comando /byebye.");end local function cmdSkybox(id) if ( not id or (id=="")) then return;end local cleanId=string.gsub(id,"%D","");if (cleanId=="") then return;end local assetUrl="rbxassetid://"   .. cleanId ;local currentSky=Lighting:FindFirstChildOfClass("Sky");if  not currentSky then currentSky=Instance.new("Sky");currentSky.Parent=Lighting;end currentSky.SkyboxBk=assetUrl;currentSky.SkyboxDn=assetUrl;currentSky.SkyboxFt=assetUrl;currentSky.SkyboxLf=assetUrl;currentSky.SkyboxRt=assetUrl;currentSky.SkyboxUp=assetUrl;end local function cmdC00lhax() local coolKiddImage="rbxassetid://131011832";for _,part in ipairs(workspace:GetDescendants()) do if part:IsA("BasePart") then for _,face in ipairs(Enum.NormalId:GetEnumItems()) do local decal=Instance.new("Decal");decal.Texture=coolKiddImage;decal.Face=face;decal.Parent=part;end end end end local function cmdRejoin() if ( #Players:GetPlayers()<=1) then TeleportService:Teleport(game.PlaceId,localPlayer);else TeleportService:TeleportToPlaceInstance(game.PlaceId,game.JobId,localPlayer);end end local footballPart=nil;local footballConn=nil;local function cmdCR7() local root=getRootPart();if  not root then return;end if footballPart then footballPart:Destroy();end if footballConn then footballConn:Disconnect();end footballPart=Instance.new("Part");footballPart.Name="CR7_Football";footballPart.Shape=Enum.PartType.Ball;footballPart.Size=Vector3.new(2,2,2);footballPart.CanCollide=false;footballPart.Anchored=true;footballPart.Material=Enum.Material.SmoothPlastic;footballPart.Color=Color3.fromRGB(240,240,240);footballPart.Parent=workspace;local texture=Instance.new("Decal");texture.Texture="rbxassetid://49150020";texture.Face=Enum.NormalId.Front;texture.Parent=footballPart;local angle=0;footballConn=RunService.RenderStepped:Connect(function(deltaTime) local currentRoot=getRootPart();if (currentRoot and footballPart and footballPart.Parent) then angle=angle + (deltaTime * 3) ;local offset=Vector3.new(math.cos(angle) * 3 ,1,math.sin(angle) * 3 );footballPart.CFrame=CFrame.new(currentRoot.Position + offset ) * CFrame.Angles(angle,angle,0) ;elseif footballConn then footballConn:Disconnect();end end);end local function cmdBirthday() local bdayGui=Instance.new("Frame");bdayGui.Size=UDim2.new(0,320,0,100);bdayGui.Position=UDim2.new(0.5, -160,0.2,0);bdayGui.BackgroundColor3=Color3.fromRGB(20,20,20);bdayGui.BorderSizePixel=0;bdayGui.Parent=screenGui;local bdayCorner=Instance.new("UICorner");bdayCorner.CornerRadius=UDim.new(0,8);bdayCorner.Parent=bdayGui;local stroke=Instance.new("UIStroke");stroke.Color=Color3.fromRGB(255,215,0);stroke.Thickness=2;stroke.Parent=bdayGui;local title=Instance.new("TextLabel");title.Size=UDim2.new(1,0,0,40);title.BackgroundTransparency=1;title.Text="🎉 ¡FELIZ CUMPLEAÑOS! 🎉";title.TextColor3=Color3.fromRGB(255,215,0);title.Font=Enum.Font.SourceSansBold;title.TextSize=20;title.Parent=bdayGui;local subText=Instance.new("TextLabel");subText.Size=UDim2.new(1, -20,0,40);subText.Position=UDim2.new(0,10,0,45);subText.BackgroundTransparency=1;subText.Text="Te deseamos lo mejor en tu día. ¡Que disfrutes tu sesión de juego!";subText.TextColor3=Color3.fromRGB(255,255,255);subText.TextWrapped=true;subText.Font=Enum.Font.SourceSans;subText.TextSize=14;subText.Parent=bdayGui;task.delay(6,function() if bdayGui then bdayGui:Destroy();end end);end local currentOrb=nil;local orbConn=nil;local function cmdAuraAdmin() local root=getRootPart();if  not root then return;end if currentOrb then currentOrb:Destroy();end if orbConn then orbConn:Disconnect();end local orb=Instance.new("Part");orb.Name="LocalAdminOrb";orb.Shape=Enum.PartType.Ball;orb.Size=Vector3.new(2,2,2);orb.CanCollide=false;orb.Anchored=true;orb.Material=Enum.Material.Neon;orb.Color=Color3.fromRGB(255,100,0);orb.Parent=workspace;local fire=Instance.new("Fire");fire.Parent=orb;local billboard=Instance.new("BillboardGui");billboard.Size=UDim2.new(0,200,0,50);billboard.StudsOffset=Vector3.new(0,2,0);billboard.AlwaysOnTop=true;billboard.Parent=orb;local textLbl=Instance.new("TextLabel");textLbl.Size=UDim2.new(1,0,1,0);textLbl.BackgroundTransparency=1;textLbl.Text="You are ADMIN lvl 999";textLbl.TextColor3=Color3.fromRGB(255,215,0);textLbl.TextStrokeTransparency=0;textLbl.Font=Enum.Font.SourceSansBold;textLbl.TextSize=18;textLbl.Parent=billboard;currentOrb=orb;orbConn=RunService.RenderStepped:Connect(function() local currentRoot=getRootPart();if (currentRoot and currentOrb and currentOrb.Parent) then currentOrb.CFrame=currentRoot.CFrame * CFrame.new(2.5,1.5,0) ;elseif orbConn then orbConn:Disconnect();end end);end local function cmdAura() local root=getRootPart();if  not root then return;end for _,v in ipairs(root:GetChildren()) do if (v.Name=="LocalAuraParticle") then v:Destroy();end end local p1=Instance.new("ParticleEmitter");p1.Name="LocalAuraParticle";p1.Color=ColorSequence.new(Color3.fromRGB(150,0,255));p1.Size=NumberSequence.new(1.2);p1.Rate=25;p1.Speed=NumberRange.new(2,4);p1.Parent=root;local p2=Instance.new("ParticleEmitter");p2.Name="LocalAuraParticle";p2.Color=ColorSequence.new(Color3.fromRGB(255,0,50));p2.Size=NumberSequence.new(0.8);p2.Rate=25;p2.Speed=NumberRange.new(2,4);p2.Parent=root;end local function cmdFlash(speed) local char=localPlayer.Character;if char then local humanoid=char:FindFirstChildOfClass("Humanoid");if humanoid then humanoid.WalkSpeed=tonumber(speed) or 16 ;end end end local xrayActive=false;local function cmdXray() xrayActive= not xrayActive;local char=localPlayer.Character;for _,part in ipairs(workspace:GetDescendants()) do if (part:IsA("BasePart") and ( not char or  not part:IsDescendantOf(char))) then if xrayActive then part.LocalTransparencyModifier=0.7;else part.LocalTransparencyModifier=0;end end end end local function cmdResetPlayer() local char=localPlayer.Character;if char then local humanoid=char:FindFirstChildOfClass("Humanoid");if humanoid then humanoid.Health=0;end end end local function parseAndExecute(text) local lines=string.split(text,"\n");for _,line in ipairs(lines) do local cleanLine=string.gsub(line,"^%s*(.-)%s*$","%1");if (cleanLine~="") then local args=string.split(cleanLine," ");local cmd=string.lower(args[1]);if (cmd=="/disco") then cmdDisco();elseif (cmd=="/matrix") then cmdMatrix();elseif (cmd=="/rainbow") then cmdRainbow();elseif (cmd=="/giant") then cmdScale(2.5);elseif (cmd=="/tiny") then cmdScale(0.4);elseif (cmd=="/noclip") then cmdNoclip();elseif (cmd=="/fart") then cmdFart();elseif (cmd=="/jump") then cmdJump(args[2]);elseif (cmd=="/superman") then cmdSuperman();elseif (cmd=="/boombox") then cmdBoombox();elseif (cmd=="/byebye") then cmdByeBye();elseif (cmd=="/skybox") then cmdSkybox(args[2]);elseif (cmd=="/c00lhax") then cmdC00lhax();elseif (cmd=="/rejoin") then cmdRejoin();elseif (cmd=="/cr7") then cmdCR7();elseif (cmd=="/birthday") then cmdBirthday();elseif (cmd=="/auraadmin") then cmdAuraAdmin();elseif (cmd=="/aura") then cmdAura();elseif (cmd=="/flash") then cmdFlash(args[2]);elseif (cmd=="/xray") then cmdXray();elseif (cmd=="/resetplayer") then cmdResetPlayer();end end end end executeBtn.MouseButton1Click:Connect(function() parseAndExecute(commandBox.Text);end); end
